No arithmetic form fits, but some rows look nearly identical, so the rules may depend on hidden groups of a and b. I'll count row and column agreement with plain clustering, and check whether those groups are shared across skills.

```python
T=np.load("T.npy"); C=np.load("C.npy")
np.set_printoptions(linewidth=250)
def groups(M,thr):
    n=len(M); ag=(M[:,None,:]==M[None,:,:]).mean(2); lab=-np.ones(n,int); g=0
    for i in range(n):
        if lab[i]<0:
            lab[i]=g
            for j in range(i+1,n):
                if lab[j]<0 and ag[i,j]>=thr: lab[j]=g
            g+=1
    return lab,ag
for s in range(4):
    for nm,M in (("rows(a)",T[s]),("cols(b)",T[s].T)):
        lab,ag=groups(M,0.6); o=ag-np.eye(32)
        print("skill",s,nm,"n groups",lab.max()+1,"mean agree",round(float(o.sum()/(32*31)),3),"nearest",np.round(np.sort(o.max(1))[[0,8,16,24,31]],2))
        print(" groups",[list(np.where(lab==g)[0]) for g in range(lab.max()+1) if (lab==g).sum()>1])
# block model: replace every cell by majority over its row group x col group, how much agrees
for s in range(4):
    for thr in (0.5,0.6,0.7):
        ra,_=groups(T[s],thr); rb,_=groups(T[s].T,thr); P=np.zeros((32,32),int)
        for i in range(ra.max()+1):
            for j in range(rb.max()+1):
                m=np.ix_(ra==i,rb==j); P[m]=np.bincount(T[s][m].ravel(),minlength=8).argmax()
        print("skill",s,"thr",thr,"groups",ra.max()+1,rb.max()+1,"block agree",round(float((P==T[s]).mean()),3))
print("cross-skill row agreement",np.round([[ (T[i]==T[j]).mean() for j in range(4)] for i in range(4)],3))
